/* DarwinPlatformHost>>eventsPumped */
void events_pumped(void)
{
    SDL_Window *local;
    SDL_Window **sw;
    int local_2;
    int *w;
    int local_3;
    int *h;
    pf_event local_4;
    pf_event *ev;
    memset(&local, 0, sizeof local);
    sw = &local;
    memset(&local_2, 0, sizeof local_2);
    w = &local_2;
    memset(&local_3, 0, sizeof local_3);
    h = &local_3;
    if (!samaltak_resize_request_of(sw, w, h)) {
        return;
    }
    memset(&local_4, 0, sizeof local_4);
    ev = &local_4;
    ev->type = PF_EV_WINDOW_RESIZED;
    ev->time_ms = platform_common_now_ms();
    ev->x = (double)*w;
    ev->y = (double)*h;
    ev->window = from_sdl_id(SDL_GetWindowID(*sw));
    if (!(ev->window == 0)) {
        platform_events_push(ev);
    }
}

/* DarwinPlatformHost>>moveDesktopWindow:x:y: */
bool move_desktop_window(SDL_Window *sw, int32_t x, int32_t y)
{
    SDL_Rect local;
    SDL_Rect *r;
    pf_event local_2;
    pf_event *ev;
    if (!samaltak_is_desktop(sw)) {
        return false;
    }
    memset(&local, 0, sizeof local);
    r = &local;
    if (!SDL_GetDisplayUsableBounds(SDL_GetPrimaryDisplay(), r)) {
        return false;
    }
    if (!SDL_SetWindowPosition(sw, r->x + x, r->y + y)) {
        return false;
    }
    memset(&local_2, 0, sizeof local_2);
    ev = &local_2;
    ev->type = PF_EV_WINDOW_MOVED;
    ev->time_ms = platform_common_now_ms();
    ev->x = (double)x;
    ev->y = (double)y;
    ev->window = from_sdl_id(SDL_GetWindowID(sw));
    platform_events_push(ev);
    return true;
}

